def minTimeForTrips(times, totalTrips):
    lo, hi = 1, min(times) * totalTrips
    while lo < hi:
        mid = (lo + hi) // 2
        done = 0
        for x in times:
            done += mid // x
        if done >= totalTrips:
            hi = mid
        else:
            lo = mid + 1
    return lo
